  const ForStmt *GuardLoops[8];
  unsigned GuardLoopCount = 0;
  DynTypedNode Node = DynTypedNode::create(*ASE);
  while (true) {
    const auto Parents = C.getASTContext().getParents(Node);
    if (Parents.empty())
