  if (!FS)
    return;

  const VarDecl *LoopVD = IndexVD;
  if (!isIncrementByOne(FS->getInc(), LoopVD, C))
    return;

  llvm::APSInt BoundExcl;
  if (!getExclusiveBoundFromCond(FS->getCond(), LoopVD, BoundExcl, C))
    return;

